#include <stdio.h>
#include <stdlib.h>

long long lisLength(const long long* arr, long long n) {
    if (n == 0) return 0;
    long long* dp = (long long*)malloc(n * sizeof(long long));
    long long result = 1;
    for (long long right = 0; right < n; ++right) {
        dp[right] = 1;
        for (long long left = 0; left < right; ++left) {
            if (arr[left] < arr[right]) {
                if (dp[left] + 1 > dp[right]) {
                    dp[right] = dp[left] + 1;
                }
            }
        }
        if (dp[right] > result) {
            result = dp[right];
        }
    }
    free(dp);
    return result;
}

int main() {
    long long test1[] = {10, 9, 2, 5, 3, 7, 101, 18};
    printf("%lld\n", lisLength(test1, 8));

    long long test2[] = {0, 1, 0, 3, 2, 3};
    printf("%lld\n", lisLength(test2, 6));

    long long test3[] = {7, 7, 7, 7, 7, 7};
    printf("%lld\n", lisLength(test3, 6));

    long long test4[] = {};
    printf("%lld\n", lisLength(test4, 0));

    long long test5[] = {1};
    printf("%lld\n", lisLength(test5, 1));

    long long test6[] = {5, 4, 3, 2, 1};
    printf("%lld\n", lisLength(test6, 5));

    long long test7[] = {1, 3, 6, 7, 9, 4, 10, 5, 6};
    printf("%lld\n", lisLength(test7, 9));

    return 0;
}

