import java.util.*;

public class Solution {
    public static long lisLength(long[] arr) {
        int n = arr.length;
        if (n == 0) return 0;

        long[] dp = new long[n];
        Arrays.fill(dp, 1);

        for (int right = 0; right < n; right++) {
            for (int left = 0; left < right; left++) {
                if (arr[left] < arr[right]) {
                    if (dp[left] + 1 > dp[right]) {
                        dp[right] = dp[left] + 1;
                    }
                }
            }
        }

        long maxLen = 1;
        for (long val : dp) {
            if (val > maxLen) maxLen = val;
        }
        return maxLen;
    }

    public static void main(String[] args) {
        // Test case 1: normal case
        long[] arr1 = {10, 22, 9, 33, 21, 50, 41, 60, 80};
        System.out.println(lisLength(arr1));

        // Test case 2: empty array
        long[] arr2 = {};
        System.out.println(lisLength(arr2));

        // Test case 3: all decreasing
        long[] arr3 = {5, 4, 3, 2, 1};
        System.out.println(lisLength(arr3));

        // Test case 4: all equal
        long[] arr4 = {7, 7, 7, 7};
        System.out.println(lisLength(arr4));

        // Test case 5: single element
        long[] arr5 = {42};
        System.out.println(lisLength(arr5));

        // Test case 6: with zero and negative values
        long[] arr6 = {0, -5, 3, -2, 1, 4};
        System.out.println(lisLength(arr6));
    }
}
